import java.util.*;

class Solution {
    private char[][] board;
    private String word;
    private int rows, cols;

    public boolean exist(char[][] board, String word) {
        if (word == null || word.isEmpty()) return true;
        this.board = board;
        this.word = word;
        this.rows = board.length;
        this.cols = board[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == word.charAt(0) && dfs(r, c, 0)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean dfs(int r, int c, int k) {
        if (k == word.length()) return true;
        if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
        if (board[r][c] != word.charAt(k)) return false;

        char saved = board[r][c];
        board[r][c] = 1;                 // 用任意非字母字符标记

        boolean found = dfs(r + 1, c, k + 1)
                || dfs(r - 1, c, k + 1)
                || dfs(r, c + 1, k + 1)
                || dfs(r, c - 1, k + 1);

        board[r][c] = saved;             // 恢复，不能漏
        return found;
    }
}

import java.util.*;

class Solution {
    private char[][] board;
    private String word;
    private int rows, cols;

    public boolean exist(char[][] board, String word) {
        if (word == null || word.isEmpty()) return true;
        this.board = board;
        this.rows = board.length;
        this.cols = board[0].length;

        int[] gridCount = new int[128];
        for (char[] row : board) {
            for (char ch : row) gridCount[ch]++;
        }
        int[] wordCount = new int[128];
        for (int i = 0; i < word.length(); i++) wordCount[word.charAt(i)]++;
        for (int i = 0; i < 128; i++) {
            if (wordCount[i] > gridCount[i]) return false;
        }

        if (gridCount[word.charAt(0)] > gridCount[word.charAt(word.length() - 1)]) {
            word = new StringBuilder(word).reverse().toString();
        }
        this.word = word;

        char first = word.charAt(0);
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == first && dfs(r, c, 0)) return true;
            }
        }
        return false;
    }

    private boolean dfs(int r, int c, int k) {
        if (k == word.length()) return true;
        if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
        if (board[r][c] != word.charAt(k)) return false;

        char saved = board[r][c];
        board[r][c] = 1;
        boolean found = dfs(r + 1, c, k + 1)
                || dfs(r - 1, c, k + 1)
                || dfs(r, c + 1, k + 1)
                || dfs(r, c - 1, k + 1);
        board[r][c] = saved;
        return found;
    }
}

import java.util.*;

class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public boolean exist(char[][] board, String word) {
        if (word == null || word.isEmpty()) return true;
        int rows = board.length;
        int cols = board[0].length;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (dfs(board, word, r, c, 0, rows, cols)) return true;
            }
        }
        return false;
    }

    private boolean dfs(char[][] board, String word, int r, int c, int k, int rows, int cols) {
        if (k == word.length()) return true;
        if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
        if (board[r][c] != word.charAt(k)) return false;

        char saved = board[r][c];
        board[r][c] = 1;

        for (int[] d : DIRS) {
            if (dfs(board, word, r + d[0], c + d[1], k + 1, rows, cols)) {
                board[r][c] = saved;
                return true;
            }
        }

        board[r][c] = saved;
        return false;
    }
}
